{"content":""""Merge user data from three sources (json / csv / parquet) into one dataset.

Priority: source_a > source_b > source_c.
Outputs: merged_users.parquet, conflicts.json
"""
import json
import os
import sys

import pandas as pd

BASE = os.path.dirname(os.path.abspath(__file__))

# normalized field -> possible raw names per source
FIELD_MAP = {
    "user_id": {"user_id", "id", "userId"},
    "name": {"full_name", "name", "userName"},
    "email": {"email", "email_address"},
    "created_date": {"registration_date", "created_at", "joined"},
    "status": {"status"},
}
SOURCES = ["source_a", "source_b", "source_c"]
FIELDS = ["name", "email", "created_date", "status"]


def norm_value(v):
    """Return a clean string, or None when the value is absent/empty."""
    if v is None:
        return None
    if isinstance(v, float) and pd.isna(v):
        return None
    s = str(v).strip()
    return s or None


def norm_date(v):
    s = norm_value(v)
    if s is None:
        return None
    ts = pd.to_datetime(s, errors="coerce")
    if pd.isna(ts):
        return s
    return ts.strftime("%Y-%m-%d")


def load_source(path):
    """Load one source file into {user_id: {field: value}}."""
    ext = os.path.splitext(path)[1].lower()
    if ext == ".json":
        with open(path, encoding="utf-8") as fh:
            raw = json.load(fh)
        if isinstance(raw, dict):
            raw = raw.get("users", list(raw.values()))
        records = raw
    elif ext == ".csv":
        records = pd.read_csv(path, dtype=str, keep_default_na=False).to_dict("records")
    elif ext == ".parquet":
        records = pd.read_parquet(path).to_dict("records")
    else:
        raise ValueError("unsupported source: " + path)

    out = {}
    for rec in records:
        rec = {str(k): v for k, v in rec.items()}
        uid = None
        for cand in FIELD_MAP["user_id"]:
            if cand in rec:
                uid = norm_value(rec[cand])
                break
        if uid is None:
            continue
        uid = int(float(uid))
        row = {}
        for field in FIELDS:
            for cand in FIELD_MAP[field]:
                if cand in rec:
                    val = norm_value(rec[cand])
                    if field == "created_date":
                        val = norm_date(rec[cand])
                    if val is not None:
                        row[field] = val
                    break
        out[uid] = row
    return out


def main():
    data = {}
    for src in SOURCES:
        path = os.path.join(BASE, "data", src, "users.json" if src == "source_a" else
                            ("users.csv" if src == "source_b" else "users.parquet"))
        data[src] = load_source(path)
        print(f"{src}: {len(data[src])} records")

    all_ids = sorted(set().union(*[set(d) for d in data.values()]))

    rows = []
    conflicts = []
    for uid in all_ids:
        merged = {}
        for field in FIELDS:
            present = {s: data[s][uid][field] for s in SOURCES
                       if uid in data[s] and field in data[s][uid]}
            if not present:
                continue
            # priority order for selection
            selected = next(present[s] for s in SOURCES if s in present)
            merged[field] = selected
            if len(set(present.values())) >= 2:
                conflicts.append({
                    "user_id": uid,
                    "field": field,
                    "values": {s: present[s] for s in SOURCES if s in present},
                    "selected": selected,
                })
        rows.append({
            "user_id": uid,
            "name": merged.get("name"),
            "email": merged.get("email"),
            "created_date": merged.get("created_date"),
            "status": merged.get("status"),
        })

    df = pd.DataFrame(rows, columns=["user_id", "name", "email", "created_date", "status"])
    df["user_id"] = df["user_id"].astype("int64")
    for col in ["name", "email", "created_date", "status"]:
        df[col] = df[col].astype("string")
    df = df.sort_values("user_id").reset_index(drop=True)

    out_parquet = os.path.join(BASE, "merged_users.parquet")
    out_conflicts = os.path.join(BASE, "conflicts.json")
    df.to_parquet(out_parquet, index=False)
    with open(out_conflicts, "w", encoding="utf-8") as fh:
        json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts},
                  fh, ensure_ascii=False, indent=2)

    print(f"merged rows: {len(df)}")
    print(f"conflicts: {len(conflicts)}")
    print(df.to_string(index=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())
