{"content":""""Independent check of merged_users.parquet and conflicts.json.

Re-derives expectations directly from the raw source files (no import of the
merge script) and compares against the produced artifacts.
"""
import json
import os
import sys

import pandas as pd

BASE = os.path.dirname(os.path.abspath(__file__))
errors = []


def check(cond, msg):
    if not cond:
        errors.append(msg)


# ---- independent re-derivation -------------------------------------------
a = json.load(open(os.path.join(BASE, "data/source_a/users.json"), encoding="utf-8"))
b = pd.read_csv(os.path.join(BASE, "data/source_b/users.csv"), dtype=str,
                keep_default_na=False).to_dict("records")
c = pd.read_parquet(os.path.join(BASE, "data/source_c/users.parquet")).to_dict("records")

exp = {}  # uid -> {field: value}
for rec in a:
    exp.setdefault(int(rec["user_id"]), {}).update(
        name=rec["full_name"], email=rec["email"], created_date=rec["registration_date"],
        status=rec.get("status"))
for rec in b:
    exp.setdefault(int(rec["id"]), {}).update(
        name=rec["name"], email=rec["email_address"], created_date=rec["created_at"])
for rec in c:
    exp.setdefault(int(rec["userId"]), {}).update(
        name=rec["userName"], email=rec["email"], created_date=rec["joined"])

# priority: a wins, then b, then c
prio = {}
for rec in c:
    prio[int(rec["userId"])] = {"name": rec["userName"], "email": rec["email"],
                                "created_date": rec["joined"]}
for rec in b:
    prio[int(rec["id"])] = {"name": rec["name"], "email": rec["email_address"],
                            "created_date": rec["created_at"]}
for rec in a:
    prio[int(rec["user_id"])] = {"name": rec["full_name"], "email": rec["email"],
                                 "created_date": rec["registration_date"],
                                 "status": rec.get("status")}

# ---- parquet --------------------------------------------------------------
df = pd.read_parquet(os.path.join(BASE, "merged_users.parquet"))
check(list(df.columns) == ["user_id", "name", "email", "created_date", "status"],
      f"unexpected columns: {list(df.columns)}")
check(str(df["user_id"].dtype) == "int64", f"user_id dtype is {df['user_id'].dtype}")
check(list(df["user_id"]) == sorted(exp), f"ids mismatch: {list(df['user_id'])} vs {sorted(exp)}")
check(len(df) == len(exp), f"row count {len(df)} != unique users {len(exp)}")

for _, row in df.iterrows():
    uid = int(row["user_id"])
    want = prio[uid]
    for field in ["name", "email", "created_date"]:
        check(row[field] == want[field],
              f"user {uid} {field}: got {row[field]!r} want {want[field]!r}")
    check(row["status"] == want.get("status") or pd.isna(row["status"]),
          f"user {uid} status: got {row['status']!r} want {want.get('status')!r}")
    check(pd.isna(row["created_date"]) or
          pd.to_datetime(row["created_date"], format="%Y-%m-%d", errors="coerce") is not pd.NaT,
          f"user {uid} created_date not YYYY-MM-DD: {row['created_date']!r}")

# ---- conflicts ------------------------------------------------------------
rep = json.load(open(os.path.join(BASE, "conflicts.json"), encoding="utf-8"))
check(set(rep) == {"total_conflicts", "conflicts"}, f"report keys: {set(rep)}")
check(rep["total_conflicts"] == len(rep["conflicts"]),
      f"total_conflicts {rep['total_conflicts']} != len {len(rep['conflicts'])}")

# expected conflicts: (uid, field) with >=2 distinct present values
srcs = {"source_a": {}, "source_b": {}, "source_c": {}}
for rec in a:
    srcs["source_a"][int(rec["user_id"])] = {"name": rec["full_name"], "email": rec["email"],
                                             "created_date": rec["registration_date"],
                                             "status": rec.get("status")}
for rec in b:
    srcs["source_b"][int(rec["id"])] = {"name": rec["name"], "email": rec["email_address"],
                                        "created_date": rec["created_at"]}
for rec in c:
    srcs["source_c"][int(rec["userId"])] = {"name": rec["userName"], "email": rec["email"],
                                            "created_date": rec["joined"]}

expected = {}
for uid in exp:
    for field in ["name", "email", "created_date", "status"]:
        present = {s: srcs[s][uid][field] for s in srcs
                   if uid in srcs[s] and srcs[s][uid].get(field) is not None}
        if len(set(present.values())) >= 2:
            expected[(uid, field)] = present

got = {}
for item in rep["conflicts"]:
    key = (item["user_id"], item["field"])
    check(key not in got, f"duplicate conflict entry {key}")
    got[key] = item
    check(set(item) == {"user_id", "field", "values", "selected"},
          f"conflict {key} keys: {set(item)}")
    check(item["values"] == expected.get(key),
          f"conflict {key} values {item['values']} != {expected.get(key)}")
    sel = next(item["values"][s] for s in ["source_a", "source_b", "source_c"]
               if s in item["values"])
    check(item["selected"] == sel, f"conflict {key} selected {item['selected']!r} != {sel!r}")

check(set(got) == set(expected),
      f"conflict set mismatch: extra={set(got) - set(expected)} missing={set(expected) - set(got)}")

if errors:
    print("FAIL")
    for e in errors:
        print(" -", e)
    sys.exit(1)
print(f"PASS: {len(df)} users, {len(got)} conflicts verified")
